import unittest
from merge import merge_sorted


class TestMergeSorted(unittest.TestCase):
    def test_empty_lists(self):
        self.assertEqual(merge_sorted([], []), [])

    def test_one_empty_list(self):
        self.assertEqual(merge_sorted([], [1, 2, 3]), [1, 2, 3])
        self.assertEqual(merge_sorted([1, 2, 3], []), [1, 2, 3])

    def test_normal_merge(self):
        self.assertEqual(merge_sorted([1, 3, 5], [2, 4, 6]), [1, 2, 3, 4, 5, 6])

    def test_trailing_elements_preserved(self):
        self.assertEqual(merge_sorted([1, 2, 3, 4], [5, 6]), [1, 2, 3, 4, 5, 6])
        self.assertEqual(merge_sorted([1, 2], [3, 4, 5, 6]), [1, 2, 3, 4, 5, 6])

    def test_single_element_lists(self):
        self.assertEqual(merge_sorted([1], [2]), [1, 2])
        self.assertEqual(merge_sorted([2], [1]), [1, 2])

    def test_duplicate_elements(self):
        self.assertEqual(merge_sorted([1, 1, 2], [1, 2, 3]), [1, 1, 1, 2, 2, 3])

