def merge_sorted(a, b):
    # Validate that both lists are sorted in ascending order
    for i in range(1, len(a)):
        if a[i] < a[i - 1]:
            raise ValueError("Input list 'a' is not sorted in ascending order")
    for i in range(1, len(b)):
        if b[i] < b[i - 1]:
            raise ValueError("Input list 'b' is not sorted in ascending order")

    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    # Append remaining elements from the longer list
    out.extend(a[i:])
    out.extend(b[j:])
    return out

